import{_ as r,o as n,c as i,ah as t}from"./chunks/framework.DDXs_i7t.js";const l=JSON.parse('{"title":"August Wöginger: Der „Harte Prosa“-Macher im Fokus","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/august-woeginger-recherche.md","filePath":"recherche/august-woeginger-recherche.md"}'),a={name:"recherche/august-woeginger-recherche.md"};function s(h,e,o,g,c,u){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="august-woginger-der-„harte-prosa-macher-im-fokus" tabindex="-1">August Wöginger: Der „Harte Prosa“-Macher im Fokus <a class="header-anchor" href="#august-woginger-der-„harte-prosa-macher-im-fokus" aria-label="Permalink to &quot;August Wöginger: Der „Harte Prosa“-Macher im Fokus&quot;">​</a></h1><p>August Wöginger, der erfahrene ÖVP-Klubobmann, steht im Zentrum zahlreicher Kontroversen, die weit über den klassischen Postenschacher hinausgehen. In unserem Projekt beleuchten wir die verschiedenen Facetten seines Wirkens.</p><h2 id="die-kernpunkte-der-recherche" tabindex="-1">Die Kernpunkte der Recherche: <a class="header-anchor" href="#die-kernpunkte-der-recherche" aria-label="Permalink to &quot;Die Kernpunkte der Recherche:&quot;">​</a></h2><ol><li><strong>Der Fall Christa Scharf:</strong> Die Intervention für eine Parteigängerin bei der Besetzung der Leitung des Finanzamtes Braunau-Ried-Schärding. Wögingers Nachricht „Bitte um Unterstützung für Christa Scharf!“ wurde zum Inbegriff der „Harten Prosa“.</li><li><strong>Die Schmid-Chats:</strong> Neue Enthüllungen aus den Mobiltelefonen von Thomas Schmid zeigen, wie tief Wöginger in das System der gegenseitigen Begünstigungen verstrickt war.</li><li><strong>Der Prozess in Linz:</strong> Die gerichtliche Aufarbeitung der Vorwürfe am Landesgericht Linz markiert einen Wendepunkt in der Wahrnehmung politischer Interventionen in Österreich.</li><li><strong>Die mediale Inszenierung:</strong> Wögingers Versuche, die Vorwürfe als „politisch motiviert“ abzutun, und sein Kampf gegen die „Kriminalisierung von Politik“.</li></ol><p>Diese Recherche bildet das Rückgrat für mehrere Szenen in „Das Horten-Mysterium“, insbesondere für die Darstellung der „Ästhetik der Kleinigkeit“ im politischen Alltag.</p>',5)])])}const m=r(a,[["render",s]]);export{l as __pageData,m as default};
